use crate::remote::auth::{write_private_json, AuthManager};
use crate::terminal::TerminalService;
use crate::worktree::WorkspaceRegistry;
use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::sync::Arc;
use tokio::sync::broadcast;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum RemoteNetworkMode {
    Off,
    LocalNetwork,
    Tailscale,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RemoteGatewayConfig {
    pub mode: RemoteNetworkMode,
    pub port: u16,
    pub allow_control: bool,
}

impl Default for RemoteGatewayConfig {
    fn default() -> Self {
        Self {
            mode: RemoteNetworkMode::Off,
            port: 43821,
            allow_control: true,
        }
    }
}

pub struct RemoteGatewayState {
    pub config: RwLock<RemoteGatewayConfig>,
    pub auth_manager: Arc<AuthManager>,
    pub terminal_service: Arc<TerminalService>,
    pub workspace_registry: WorkspaceRegistry,
    pub event_tx: broadcast::Sender<String>,
    pub is_running: RwLock<bool>,
    pub bound_address: RwLock<Option<String>>,
    config_path: Option<PathBuf>,
}

impl RemoteGatewayState {
    pub fn new(terminal_service: Arc<TerminalService>, workspace_registry: WorkspaceRegistry) -> Self {
        Self::new_with_paths(terminal_service, workspace_registry, None, None)
    }

    pub fn new_persistent(
        terminal_service: Arc<TerminalService>,
        workspace_registry: WorkspaceRegistry,
    ) -> Self {
        let base = remote_data_dir();
        Self::new_with_paths(
            terminal_service,
            workspace_registry,
            Some(base.join("remote-config.json")),
            Some(base.join("remote-auth.json")),
        )
    }

    pub fn new_with_paths(
        terminal_service: Arc<TerminalService>,
        workspace_registry: WorkspaceRegistry,
        config_path: Option<PathBuf>,
        auth_path: Option<PathBuf>,
    ) -> Self {
        let (event_tx, _) = broadcast::channel(1024);
        let config = config_path
            .as_deref()
            .and_then(|path| std::fs::read(path).ok())
            .and_then(|bytes| serde_json::from_slice::<RemoteGatewayConfig>(&bytes).ok())
            .unwrap_or_default();
        Self {
            config: RwLock::new(config),
            auth_manager: Arc::new(AuthManager::with_persistence(auth_path)),
            terminal_service,
            workspace_registry,
            event_tx,
            is_running: RwLock::new(false),
            bound_address: RwLock::new(None),
            config_path,
        }
    }

    pub fn emit_event(&self, event_json: String) {
        let _ = self.event_tx.send(event_json);
    }

    pub fn persist_config(&self) -> std::io::Result<()> {
        let Some(path) = self.config_path.as_deref() else {
            return Ok(());
        };
        write_private_json(path, &*self.config.read())
    }
}

fn remote_data_dir() -> PathBuf {
    if let Some(path) = std::env::var_os("FERRYX_DATA_DIR") {
        return PathBuf::from(path).join("remote");
    }
    if let Some(home) = std::env::var_os("HOME") {
        return PathBuf::from(home).join(".ferryx").join("remote");
    }
    std::env::temp_dir().join("ferryx").join("remote")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::terminal::{PtyManager, TerminalOutputHub};

    #[test]
    fn gateway_config_survives_reopen() {
        let dir = tempfile::TempDir::new().expect("tempdir");
        let config_path = dir.path().join("config.json");
        let auth_path = dir.path().join("auth.json");
        let pty = Arc::new(PtyManager::new());
        let hub = Arc::new(TerminalOutputHub::default());
        let terminal = Arc::new(TerminalService::new(pty, hub));
        let registry = WorkspaceRegistry::new();
        let state = RemoteGatewayState::new_with_paths(
            Arc::clone(&terminal),
            registry.clone(),
            Some(config_path.clone()),
            Some(auth_path.clone()),
        );
        state.config.write().mode = RemoteNetworkMode::LocalNetwork;
        state.config.write().port = 45678;
        state.persist_config().expect("persist");

        let reopened = RemoteGatewayState::new_with_paths(
            terminal,
            registry,
            Some(config_path),
            Some(auth_path),
        );
        let config = reopened.config.read();
        assert_eq!(config.mode, RemoteNetworkMode::LocalNetwork);
        assert_eq!(config.port, 45678);
    }
}

use crate::ipc::IpcError;
use crate::remote::auth::{DeviceInfo, DevicePermission};
use crate::remote::server::{start_remote_server, RemoteServerHandle};
use crate::remote::state::{RemoteGatewayState, RemoteNetworkMode};
use crate::remote::tailscale::{check_tailscale_status, SystemCommandRunner, TailscaleStatus};
use parking_lot::Mutex;
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tauri::State;

#[derive(Clone)]
pub struct RemoteGatewayManager {
    state: Arc<RemoteGatewayState>,
    server_handle: Arc<Mutex<Option<RemoteServerHandle>>>,
}

impl RemoteGatewayManager {
    pub fn new(state: Arc<RemoteGatewayState>) -> Self {
        Self {
            state,
            server_handle: Arc::new(Mutex::new(None)),
        }
    }

    pub fn state(&self) -> &Arc<RemoteGatewayState> {
        &self.state
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RemoteGatewayStatusResponse {
    pub enabled: bool,
    pub mode: RemoteNetworkMode,
    pub port: u16,
    pub bound_address: Option<String>,
    pub local_ip: Option<String>,
    pub tailscale: TailscaleStatus,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct EnableRemoteGatewayRequest {
    pub mode: RemoteNetworkMode,
    pub port: Option<u16>,
    pub allow_control: Option<bool>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CreatePairingCodeResponse {
    pub code: String,
    pub expires_in_seconds: u32,
}

#[tauri::command]
pub async fn cmd_remote_status(
    manager: State<'_, Arc<RemoteGatewayManager>>,
) -> Result<RemoteGatewayStatusResponse, IpcError> {
    let state = manager.state();
    let config = state.config.read().clone();
    let is_running = *state.is_running.read();
    let bound_address = state.bound_address.read().clone();
    let tailscale = check_tailscale_status(&SystemCommandRunner);

    let local_ip = get_local_ip();
    Ok(RemoteGatewayStatusResponse {
        enabled: is_running,
        mode: config.mode,
        port: config.port,
        bound_address,
        local_ip,
        tailscale,
    })
}

#[tauri::command]
pub async fn cmd_remote_enable(
    manager: State<'_, Arc<RemoteGatewayManager>>,
    request: EnableRemoteGatewayRequest,
) -> Result<RemoteGatewayStatusResponse, IpcError> {
    let state = manager.state();

    // Stop existing server if running
    if let Some(handle) = manager.server_handle.lock().take() {
        handle.stop();
    }

    {
        let mut config = state.config.write();
        config.mode = request.mode;
        if let Some(port) = request.port {
            config.port = port;
        }
        if let Some(allow_ctrl) = request.allow_control {
            config.allow_control = allow_ctrl;
        }
    }

    if request.mode != RemoteNetworkMode::Off {
        let (handle, _addr) = start_remote_server(Arc::clone(state))
            .await
            .map_err(|e| IpcError::internal(format!("Failed to start remote gateway: {e}")))?;
        *manager.server_handle.lock() = Some(handle);
    }

    cmd_remote_status(manager).await
}

#[tauri::command]
pub async fn cmd_remote_disable(
    manager: State<'_, Arc<RemoteGatewayManager>>,
) -> Result<RemoteGatewayStatusResponse, IpcError> {
    if let Some(handle) = manager.server_handle.lock().take() {
        handle.stop();
    }
    state_set_off(manager.state());
    cmd_remote_status(manager).await
}

fn state_set_off(state: &Arc<RemoteGatewayState>) {
    let mut config = state.config.write();
    config.mode = RemoteNetworkMode::Off;
    *state.is_running.write() = false;
    *state.bound_address.write() = None;
}

#[tauri::command]
pub async fn cmd_remote_pairing_create(
    manager: State<'_, Arc<RemoteGatewayManager>>,
    permission: Option<DevicePermission>,
) -> Result<CreatePairingCodeResponse, IpcError> {
    let perm = permission.unwrap_or(DevicePermission::Control);
    let code = manager.state().auth_manager.create_pairing_code(perm);
    Ok(CreatePairingCodeResponse {
        code,
        expires_in_seconds: 60,
    })
}

#[tauri::command]
pub async fn cmd_remote_devices(
    manager: State<'_, Arc<RemoteGatewayManager>>,
) -> Result<Vec<DeviceInfo>, IpcError> {
    Ok(manager.state().auth_manager.list_devices())
}

#[tauri::command]
pub async fn cmd_remote_device_revoke(
    manager: State<'_, Arc<RemoteGatewayManager>>,
    device_id: String,
) -> Result<bool, IpcError> {
    Ok(manager.state().auth_manager.revoke_device(&device_id))
}

#[tauri::command]
pub async fn cmd_tailscale_status() -> Result<TailscaleStatus, IpcError> {
    Ok(check_tailscale_status(&SystemCommandRunner))
}

fn get_local_ip() -> Option<String> {
    use std::net::UdpSocket;
    let socket = UdpSocket::bind("0.0.0.0:0").ok()?;
    socket.connect("8.8.8.8:80").ok()?;
    socket.local_addr().ok().map(|addr| addr.ip().to_string())
}

use super::*;
use crate::terminal::TerminalService;
use std::sync::Arc;

struct MockTailscaleRunner {
    installed: bool,
    running: bool,
    self_dns: Option<String>,
}

impl CommandRunner for MockTailscaleRunner {
    fn run(&self, program: &str, args: &[&str]) -> Result<String, String> {
        if program != "tailscale" {
            return Err("not tailscale".into());
        }
        if !self.installed {
            return Err("command not found".into());
        }
        if args.contains(&"status") {
            let json = serde_json::json!({
                "BackendState": if self.running { "Running" } else { "Stopped" },
                "CurrentTailnet": { "Name": "test-tailnet" },
                "Self": { "DNSName": self.self_dns.as_deref().unwrap_or("my-mac.test.ts.net.") }
            });
            Ok(json.to_string())
        } else if args.contains(&"serve") {
            Ok(r#"{"TCP":{"43821":{"HTTPS":true}}}"#.into())
        } else {
            Ok("".into())
        }
    }
}

#[test]
fn test_tailscale_status_parsing() {
    let runner = MockTailscaleRunner {
        installed: true,
        running: true,
        self_dns: Some("my-mac.tailnet.ts.net.".into()),
    };
    let status = check_tailscale_status(&runner);
    assert!(status.installed);
    assert!(status.running);
    assert_eq!(status.self_dns, Some("my-mac.tailnet.ts.net".into()));
    assert_eq!(status.tailnet_name, Some("test-tailnet".into()));
}

#[test]
fn test_auth_manager_pairing_and_revocation() {
    let auth = AuthManager::new();
    let code = auth.create_pairing_code(DevicePermission::Control);

    // Invalid code fails
    assert!(auth.exchange_pairing_code("invalid_code", "test-device").is_err());

    // Valid code succeeds
    let (token, device) = auth.exchange_pairing_code(&code, "test-device").expect("exchange success");
    assert_eq!(device.permission, DevicePermission::Control);
    assert!(!device.revoked);

    // Code is single use
    assert!(auth.exchange_pairing_code(&code, "test-device-2").is_err());

    // Validate token
    let validated = auth.validate_token(&token).expect("validate success");
    assert_eq!(validated.id, device.id);

    // Revoke device
    assert!(auth.revoke_device(&device.id));
    assert!(matches!(auth.validate_token(&token), Err(AuthError::RevokedDevice)));
}

#[tokio::test]
async fn test_remote_server_health_and_lifecycle() {
    let terminal_service = Arc::new(TerminalService::default());
    let state = Arc::new(RemoteGatewayState::new(terminal_service, crate::worktree::WorkspaceRegistry::new()));

    *state.config.write() = RemoteGatewayConfig {
        mode: RemoteNetworkMode::Tailscale,
        port: 0, // OS assigns available port
        allow_control: true,
    };

    let (handle, addr) = start_remote_server(Arc::clone(&state)).await.expect("start server");
    assert!(addr.ip().is_unspecified() || addr.ip().is_loopback());

    // Health endpoint
    let client = reqwest_like_health(&format!("http://{addr}/api/v1/health")).await;
    assert!(client);

    handle.stop();
}

async fn reqwest_like_health(url: &str) -> bool {
    // simple TCP request
    let parsed: std::net::SocketAddr = url.trim_start_matches("http://").trim_end_matches("/api/v1/health").parse().unwrap();
    if let Ok(mut stream) = tokio::net::TcpStream::connect(parsed).await {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};
        let req = b"GET /api/v1/health HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n";
        let _ = stream.write_all(req).await;
        let mut buf = [0u8; 1024];
        if let Ok(n) = stream.read(&mut buf).await {
            let res = String::from_utf8_lossy(&buf[..n]);
            return res.contains("200 OK") && res.contains(r#""status":"ok""#);
        }
    }
    false
}


#[tokio::test]
async fn test_remote_server_serves_spa_index_html() {
    let terminal_service = Arc::new(TerminalService::default());
    let state = Arc::new(RemoteGatewayState::new(terminal_service, crate::worktree::WorkspaceRegistry::new()));

    *state.config.write() = RemoteGatewayConfig {
        mode: RemoteNetworkMode::LocalNetwork,
        port: 0,
        allow_control: true,
    };

    let (handle, addr) = start_remote_server(Arc::clone(&state)).await.expect("start server");

    let parsed: std::net::SocketAddr = addr;
    if let Ok(mut stream) = tokio::net::TcpStream::connect(parsed).await {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};
        let req = b"GET / HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n";
        let _ = stream.write_all(req).await;
        let mut buf = [0u8; 4096];
        if let Ok(n) = stream.read(&mut buf).await {
            let res = String::from_utf8_lossy(&buf[..n]);
            assert!(res.contains("200 OK"));
            assert!(res.contains("<!doctype html>") || res.contains("<html"));
        }
    }

    handle.stop();
}

#[test]
fn test_derive_session_metadata_matches_workspace() {
    let dir = tempfile::TempDir::new().expect("tempdir");
    let repo_root = dir.path().join("repo");
    std::fs::create_dir_all(&repo_root).unwrap();
    crate::worktree::run_git(&repo_root, &["init"]).expect("git init");
    let wt = repo_root.join("wt-a");
    std::fs::create_dir_all(&wt).unwrap();

    let registry = crate::worktree::WorkspaceRegistry::new();
    registry.register("ws1", &repo_root).expect("register");
    let cache = crate::remote::server::WorkspaceSnapshotCache::build(&registry);

    // Path inside a registered workspace but not a listed git worktree (e.g. an
    // ad-hoc subdirectory terminal): workspace matches, label falls back to the
    // path relative to the workspace root.
    let (ws_id, label) = cache.derive_session_metadata(Some(&wt));
    assert_eq!(ws_id.as_deref(), Some("ws1"));
    assert_eq!(label.as_deref(), Some("wt-a"));

    // Nested ad-hoc subdirectory: label is the full relative path, not just the
    // leaf directory name, so it stays informative and collision-resistant.
    let nested = wt.join("src").join("feature");
    std::fs::create_dir_all(&nested).unwrap();
    let (ws_id, label) = cache.derive_session_metadata(Some(&nested));
    assert_eq!(ws_id.as_deref(), Some("ws1"));
    assert_eq!(label.as_deref(), Some("wt-a/src/feature"));

    // Path outside any registered workspace: no workspace id, best-effort label.
    let other = dir.path().join("other");
    std::fs::create_dir_all(&other).unwrap();
    let (ws_id, label) = cache.derive_session_metadata(Some(&other));
    assert_eq!(ws_id, None);
    assert_eq!(label.as_deref(), Some("other"));

    // No owning worktree path at all.
    assert_eq!(cache.derive_session_metadata(None), (None, None));

    // The repo root itself (a session opened directly at the workspace root, not
    // in any subdirectory): must not panic, and should yield a sensible, non-empty
    // label. The root is git's "main" worktree entry, so it resolves via the
    // checked-out branch name rather than the relative-path fallback.
    let (ws_id, label) = cache.derive_session_metadata(Some(&repo_root));
    assert_eq!(ws_id.as_deref(), Some("ws1"));
    assert!(label.as_deref().is_some_and(|l| !l.is_empty()));

    // Nonexistent path (e.g. a worktree deleted after the session was spawned)
    // inside the registered root: canonicalize() fails and falls back to the raw
    // path without panicking.
    let missing = repo_root.join("does-not-exist");
    let (ws_id, label) = cache.derive_session_metadata(Some(&missing));
    assert_eq!(ws_id.as_deref(), Some("ws1"));
    assert_eq!(label.as_deref(), Some("does-not-exist"));
}

use crate::ipc::terminal::{get_cached_cwd, process_cwd};
use crate::ipc::*;
use crate::terminal::TerminalService;
use crate::worktree::{run_git, WorkspaceRegistry, WorktreeIdentity};
use base64::{engine::general_purpose::STANDARD, Engine as _};
use std::sync::Arc;
use tauri::{Listener, Manager};
use tempfile::TempDir;


fn setup_workspace() -> (TempDir, WorkspaceRegistry) {
    let repo = TempDir::new().expect("repo tempdir");
    run_git(repo.path(), &["init"]).expect("git init");
    run_git(repo.path(), &["config", "user.email", "test@example.com"]).expect("email");
    run_git(repo.path(), &["config", "user.name", "Test User"]).expect("name");
    std::fs::write(repo.path().join("README.md"), "initial\n").expect("README");
    run_git(repo.path(), &["add", "README.md"]).expect("add");
    run_git(repo.path(), &["commit", "-m", "initial commit"]).expect("commit");

    let registry = WorkspaceRegistry::new();
    registry.register("workspace-test", repo.path()).expect("register");
    (repo, registry)
}

#[tokio::test]
async fn tauri_mock_terminal_events_use_registered_workspace() {
    let (_repo, registry) = setup_workspace();
    let app = tauri::test::mock_builder()
        .manage(Arc::new(TerminalService::default()))
        .manage(registry)
        .build(tauri::test::mock_context(tauri::test::noop_assets()))
        .expect("mock app");

    let terminal_service = app.state::<Arc<TerminalService>>();
    let registry_state = app.state::<WorkspaceRegistry>();
    let (tx, mut rx_event) = tokio::sync::mpsc::channel::<TerminalOutputPayload>(16);
    app.listen(TERMINAL_OUTPUT_EVENT, move |event: tauri::Event| {
        if let Ok(payload) = serde_json::from_str::<TerminalOutputPayload>(event.payload()) {
            let _ = tx.try_send(payload);
        }
    });

    let spawned = cmd_terminal_spawn(
        app.handle().clone(),
        terminal_service.clone(),
        registry_state,
        SpawnTerminalRequest {
            workspace_id: "workspace-test".into(),
            worktree: None,
            cwd: None,
            cols: Some(80),
            rows: Some(24),
        },
    )
    .await
    .expect("spawn");

    cmd_terminal_write(
        terminal_service.clone(),
        spawned.session_id.clone(),
        "echo hello_orca_terminal\n".into(),
    )
    .await
    .expect("write");

    let mut collected = Vec::new();
    tokio::time::timeout(tokio::time::Duration::from_secs(5), async {
        while !String::from_utf8_lossy(&collected).contains("hello_orca_terminal") {
            let payload = rx_event.recv().await.expect("terminal output");
            assert_eq!(payload.session_id, spawned.session_id);
            collected.extend_from_slice(&STANDARD.decode(payload.data).expect("base64"));
        }
    })
    .await
    .expect("terminal output timeout");

    cmd_terminal_resize(
        terminal_service.clone(),
        spawned.session_id.clone(),
        120,
        40,
    )
    .await
    .expect("resize");
    let sessions = cmd_terminal_list(terminal_service.clone()).await.expect("list");
    assert!(sessions
        .iter()
        .any(|session| session.session_id == spawned.session_id));

    cmd_terminal_close(terminal_service.clone(), spawned.session_id.clone())
        .await
        .expect("close");
    cmd_terminal_close(terminal_service.clone(), spawned.session_id.clone())
        .await
        .expect("idempotent close");
    let sessions = cmd_terminal_list(terminal_service).await.expect("list after");
    assert!(!sessions
        .iter()
        .any(|session| session.session_id == spawned.session_id));
}

#[tokio::test]
async fn tauri_mock_worktree_commands_use_identity_contract() {
    let (repo, registry) = setup_workspace();
    let app = tauri::test::mock_builder()
        .manage(Arc::new(TerminalService::default()))
        .manage(registry)
        .build(tauri::test::mock_context(tauri::test::noop_assets()))
        .expect("mock app");
    let registry_state = app.state::<WorkspaceRegistry>();
    let identity = WorktreeIdentity {
        ws_id: "ws-ipc".into(),
        slug: "task-ipc".into(),
    };

    let initial = cmd_worktree_list(registry_state.clone(), "workspace-test".into())
        .await
        .expect("initial list");
    assert_eq!(initial.len(), 1);

    let created = cmd_worktree_create(
        app.handle().clone(),
        registry_state.clone(),
        CreateWorktreeRequest {
            workspace_id: "workspace-test".into(),
            worktree: identity.clone(),
            base_ref: None,
        },
    )
    .await
    .expect("create");
    assert!(created.path.exists());

    let status = cmd_worktree_status(
        app.handle().clone(),
        registry_state.clone(),
        WorktreeStatusRequest {
            workspace_id: "workspace-test".into(),
            worktree: identity.clone(),
        },
    )
    .await
    .expect("status");
    assert!(!status.is_dirty);

    cmd_worktree_delete(
        app.handle().clone(),
        registry_state.clone(),
        DeleteWorktreeRequest {
            workspace_id: "workspace-test".into(),
            worktree: identity.clone(),
            delete_branch: Some(true),
        },
    )
    .await
    .expect("delete");

    assert!(!created.path.exists());
    let branches = run_git(repo.path(), &["branch", "--list"]).expect("list branches");
    assert!(!branches.contains("orca/ws-ipc/task-ipc"));

    let final_list = cmd_worktree_list(registry_state, "workspace-test".into())
        .await
        .expect("final list");
    assert_eq!(final_list.len(), 1);
}

#[tokio::test]
async fn terminal_global_events_preserve_raw_bytes_and_lifecycle() {
    let (_repo, registry) = setup_workspace();
    let app = tauri::test::mock_builder()
        .manage(Arc::new(TerminalService::default()))
        .manage(registry)
        .build(tauri::test::mock_context(tauri::test::noop_assets()))
        .expect("mock app");

    let terminal_service = app.state::<Arc<TerminalService>>();
    let registry_state = app.state::<WorkspaceRegistry>();
    let (output_tx, mut output_rx) = tokio::sync::mpsc::channel::<TerminalOutputPayload>(32);
    let (lifecycle_tx, mut lifecycle_rx) =
        tokio::sync::mpsc::channel::<TerminalLifecyclePayload>(8);

    app.listen(TERMINAL_OUTPUT_EVENT, move |event: tauri::Event| {
        if let Ok(payload) = serde_json::from_str::<TerminalOutputPayload>(event.payload()) {
            let _ = output_tx.try_send(payload);
        }
    });
    app.listen(TERMINAL_LIFECYCLE_EVENT, move |event: tauri::Event| {
        if let Ok(payload) = serde_json::from_str::<TerminalLifecyclePayload>(event.payload()) {
            let _ = lifecycle_tx.try_send(payload);
        }
    });

    let spawned = cmd_terminal_spawn(
        app.handle().clone(),
        terminal_service.clone(),
        registry_state,
        SpawnTerminalRequest {
            workspace_id: "workspace-test".into(),
            worktree: None,
            cwd: None,
            cols: Some(80),
            rows: Some(24),
        },
    )
    .await
    .expect("spawn");

    let started = tokio::time::timeout(tokio::time::Duration::from_secs(2), lifecycle_rx.recv())
        .await
        .expect("started timeout")
        .expect("started event");
    assert_eq!(started.session_id, spawned.session_id);
    assert_eq!(started.state, TerminalLifecycleState::Started);

    cmd_terminal_write(
        terminal_service.clone(),
        spawned.session_id.clone(),
        "printf '\\377\\376\\n'\n".into(),
    )
    .await
    .expect("write raw bytes");

    let mut raw = Vec::new();
    tokio::time::timeout(tokio::time::Duration::from_secs(5), async {
        while !raw.windows(2).any(|window| window == [0xff, 0xfe]) {
            let payload = output_rx.recv().await.expect("output event");
            assert_eq!(payload.session_id, spawned.session_id);
            raw.extend_from_slice(&STANDARD.decode(payload.data).expect("base64 payload"));
        }
    })
    .await
    .expect("raw output timeout");

    cmd_terminal_close(terminal_service, spawned.session_id.clone())
        .await
        .expect("close");

    let exited = tokio::time::timeout(tokio::time::Duration::from_secs(2), lifecycle_rx.recv())
        .await
        .expect("exited timeout")
        .expect("exited event");
    assert_eq!(exited.session_id, spawned.session_id);
    assert_eq!(exited.state, TerminalLifecycleState::Exited);
    assert!(exited.reason.is_none());
}

